# Re-parse more carefully
parents = set()
for line in edges_text.strip().split('\n'):
    line = line.strip()
    if '->' in line:
        parts = line.split('->')
        source = parts[0].strip()
        target = parts[1].strip()
        if target == 'e4da3b7fbb':
            print(f"Found edge: {source} -> {target}")
            if source != 'e4da3b7fbb':
                parents.add(source)

print("\nFinal parents (excluding self):", sorted(parents))
